import{_ as a,o as n,c as l,a3 as c}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-21 — Xác minh KYC (CCCD)","description":"","frontmatter":{"title":"SC-21 — Xác minh KYC (CCCD)"},"headers":[],"relativePath":"wireframes/user/sc-21-xac-minh-kyc.md","filePath":"wireframes/user/sc-21-xac-minh-kyc.md","lastUpdated":null}'),i={name:"wireframes/user/sc-21-xac-minh-kyc.md"};function t(p,s,e,d,h,o){return n(),l("div",null,[...s[0]||(s[0]=[c('<h1 id="sc-21-—-xac-minh-danh-tinh-kyc-cccd" tabindex="-1">SC-21 — Xác minh danh tính KYC (CCCD) <a class="header-anchor" href="#sc-21-—-xac-minh-danh-tinh-kyc-cccd" aria-label="Permalink to &quot;SC-21 — Xác minh danh tính KYC (CCCD)&quot;">​</a></h1><p><span class="wf-badge danger">MÀN NHẠY CẢM — DỮ LIỆU CÁ NHÂN (NĐ13)</span> <span class="wf-badge info">Route: /xac-minh</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-21 · docs/03 UC-02 · docs/02 FR-KYC · docs/08 BR-KYC · docs/06 §5</span></p><p><strong>Ai xem màn này</strong>: Thành viên chưa xác minh (KYC NONE) cần mở khóa tính năng · thành viên bị REJECTED muốn nộp lại · thành viên PENDING/APPROVED quay lại xem trạng thái. <strong>Mục đích / cảm xúc thiết kế</strong>: đây là màn user giao nộp <strong>dữ liệu nhạy cảm nhất</strong> (CCCD + ảnh 2 mặt). Cảm xúc phải đạt: <em>minh bạch tuyệt đối</em> — nói rõ thu gì, giữ thế nào, ai xem được, xóa khi nào; <em>không gấp gáp</em>; lỗi hướng dẫn sửa được ngay (chụp lại thế nào), không cộc lốc. <strong>Ví dụ số dùng trong bản vẽ</strong>: <code>Nguyễn Văn Demo</code> (NĐ) · CCCD 12 số <code>001090123456</code> · DOB <code>20/05/1990</code> · nộp lúc <code>10/10/2026 09:30</code> (GMT+7) · SLA duyệt ≤48h → hẹn <code>12/10/2026 09:30</code> · giới hạn 3 hồ sơ/30 ngày.</p><h2 id="_1-desktop-—-buoc-1-3-thong-tin-cccd" tabindex="-1">1. Desktop — Bước 1/3: thông tin CCCD <a class="header-anchor" href="#_1-desktop-—-buoc-1-3-thong-tin-cccd" aria-label="Permalink to &quot;1. Desktop — Bước 1/3: thông tin CCCD&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/xac-minh</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">NĐ</span></span></div><div class="wf-container"><div class="wf-breadcrumb">Dashboard › <b>Xác minh danh tính</b></div><div class="wf-col" style="max-width:640px;margin:0 auto;"><div class="wf-card"><div class="pad wf-col" style="gap:12px;"><div class="wf-col" style="gap:2px;"><span class="wf-title lg">Xác minh danh tính (CCCD) <span class="wf-callout">1</span></span><span class="wf-small">Bắt buộc trước khi: đăng tin bán · đăng ký đấu giá · đặt lịch xem nhà</span></div><div class="wf-steps"><span class="wf-step active">1 · Thông tin CCCD</span><span class="wf-step">2 · Ảnh 2 mặt</span><span class="wf-step">3 · Xác nhận &amp; gửi</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Họ và tên (đúng trên CCCD) <span class="wf-danger-text">*</span></span><div class="wf-input filled"><span>NGUYỄN VĂN DEMO</span><span class="caret">✎</span></div><span class="wf-small wf-muted">Prefill từ hồ sơ (viết hoa không dấu CCCD). Tên phải trùng khít CCCD — ADMIN đối chiếu khi duyệt, lệch sẽ bị từ chối <span class="wf-callout">2</span></span></div><div class="wf-row" style="gap:12px;"><div class="wf-col" style="flex:1;gap:4px;"><span class="wf-small wf-strong">Ngày sinh <span class="wf-danger-text">*</span></span><div class="wf-input filled"><span>20/05/1990</span><span class="caret">📅</span></div><span class="wf-small wf-muted">dd/MM/yyyy · phải đủ 18 tuổi tại thời điểm nộp <span class="wf-callout">3</span></span></div><div class="wf-col" style="flex:1;gap:4px;"><span class="wf-small wf-strong">Số CCCD (12 chữ số) <span class="wf-danger-text">*</span></span><div class="wf-input filled"><span>001090123456</span><span class="caret">✎</span></div><span class="wf-small wf-muted">12/12 số · chỉ nhận chữ số <span class="wf-callout">4</span></span></div></div><div class="wf-note" style="border-width:2px;"><b>🔒 Dữ liệu cá nhân nhạy cảm — Nghị định 13/2023/NĐ-CP</b> <span class="wf-callout warn">5</span><br> Số CCCD và ảnh giấy tờ của bạn được: (1) <b>mã hóa AES-256</b> khi lưu; (2) chỉ ADMIN duyệt hồ sơ xem được, qua liên kết tạm thời hết hạn sau <b>5 phút</b>; (3) <b>không bao giờ</b> hiển thị công khai hay trả về API public; (4) hồ sơ bị từ chối quá <b>180 ngày</b> → ảnh và số CCCD tự động xóa. Gửi hồ sơ = bạn đồng ý phạm vi xử lý này. </div><div class="wf-row between" style="margin-top:4px;"><span class="wf-btn ghost">Hủy</span><span class="wf-btn primary">Tiếp tục → Bước 2: ảnh CCCD</span></div></div></div><span class="wf-small wf-center">Cần trợ giúp? CSKH 1900-xxx (08:00–20:00)</span></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 SC-21 · docs/03 UC-02 · docs/08 BR-KYC)</div><ol><li><span class="num">1</span><span><b>Wizard 3 bước</b> — thanh step luôn visible, không cho nhảy bước (chỉ Quay lại bước trước). Mỗi bước validate trước khi cho tiếp. <span class="ref">docs/05 §3 SC-21</span></span></li><li><span class="num">2</span><span>Họ tên 2–100 ký tự, prefill từ <code>users.full_name</code>; ADMIN đối chiếu trực quan tên ↔ CCCD khi duyệt (v1 manual). Ghi rõ hậu quả &quot;lệch sẽ bị từ chối&quot; ngay tại field để giảm vòng lặp reject. <span class="ref">BR-KYC-02</span> <span class="ref">FR-KYC-01</span></span></li><li><span class="num">3</span><span>DOB ≥18 tuổi tính theo <b>giờ server</b> lúc nộp → vi phạm trả 422 <code>KYC_UNDERAGE</code>, field error: &quot;Bạn phải đủ 18 tuổi tại thời điểm nộp hồ sơ&quot;. <span class="ref">BR-KYC-01</span> <span class="ref">UC-02 EF-2</span></span></li><li><span class="num">4</span><span>CCCD validate client <b>chỉ đúng 12 chữ số</b> (chặn ký tự lạ khi gõ, đếm 0/12 → 12/12); server re-check <code>^[0-9]{12}$</code>. Sai → field error tại ô: &quot;CCCD phải đúng 12 chữ số&quot;. Không format dấu cách trong value gửi đi. <span class="ref">FR-KYC-01</span> <span class="ref">BR-KYC-01</span></span></li><li><span class="num">5</span><span><b>Cảnh báo NĐ13 đặt ở bước 1, không dồn xuống bước cuối</b> — user phải biết phạm vi xử lý trước khi nhập dữ liệu, không phải sau khi lỡ nộp. Nội dung khớp NFR-S-05: mã hóa at-rest, signed URL TTL ≤5 phút, không public, retention purge 180 ngày (REJECTED) / 365 ngày (tài khoản đóng). <span class="ref">NFR-S-05</span> <span class="ref">docs/07 §2.3/§2.6</span> <span class="ref">BR-KYC-07</span></span></li></ol></div><h2 id="_2-desktop-—-buoc-2-3-upload-anh-2-mat-cccd-dropzone-crop-preview" tabindex="-1">2. Desktop — Bước 2/3: upload ảnh 2 mặt CCCD (dropzone + crop preview) <a class="header-anchor" href="#_2-desktop-—-buoc-2-3-upload-anh-2-mat-cccd-dropzone-crop-preview" aria-label="Permalink to &quot;2. Desktop — Bước 2/3: upload ảnh 2 mặt CCCD (dropzone + crop preview)&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/xac-minh</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">NĐ</span></span></div><div class="wf-container"><div class="wf-col" style="max-width:640px;margin:0 auto;"><div class="wf-card"><div class="pad wf-col" style="gap:12px;"><span class="wf-title lg">Ảnh CCCD 2 mặt <span class="wf-callout">6</span></span><div class="wf-steps"><span class="wf-step done">1 · Thông tin ✓</span><span class="wf-step active">2 · Ảnh 2 mặt</span><span class="wf-step">3 · Xác nhận &amp; gửi</span></div><div class="wf-grid"><div class="wf-col" style="gap:6px;"><span class="wf-small wf-strong">MẶT TRƯỚC <span class="wf-danger-text">*</span></span><div class="wf-img" style="min-height:150px;"><span>ẢNH CCCD MẶT TRƯỚC — đã tải lên (crop preview)</span></div><div class="wf-row" style="gap:6px;"><span class="wf-btn sm">Xem lớn</span><span class="wf-btn sm ghost">Tải ảnh khác</span><span class="wf-small wf-ok-text" style="align-self:center;">✓ Đã sẵn sàng <span class="wf-callout">7</span></span></div></div><div class="wf-col" style="gap:6px;"><span class="wf-small wf-strong">MẶT SAU <span class="wf-danger-text">*</span></span><div class="wf-img" style="min-height:150px;border-style:dashed;"><span>KÉO THẢ HOẶC BẤM ĐỂ TẢI LÊN</span></div><span class="wf-field-error">Bắt buộc đủ 2 ảnh trước khi tiếp tục <span class="wf-callout danger">8</span></span></div></div><div class="wf-note"><b>Yêu cầu ảnh</b> — JPEG/PNG/WEBP, ≤5MB mỗi ảnh; chụp phẳng, đủ sáng, <b>thấy đủ 4 góc</b>, không che mất dòng chữ/số nào; không dùng ảnh chụp lại màn hình. Ảnh mờ là lý do bị từ chối phổ biến nhất. </div><div class="wf-row between" style="margin-top:4px;"><span class="wf-btn ghost">← Bước 1</span><span class="wf-btn disabled">Tiếp tục → Bước 3 (thiếu mặt sau)</span></div></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích upload</div><ol><li><span class="num">6</span><span>Upload qua <code>POST /media/upload</code> kind=<code>kyc_doc</code> (multipart, rate 30/giờ/user) ngay khi chọn file — không đợi submit form. Đang upload: thumbnail skeleton + % tiến trình; xong hiện crop preview (crop chỉ là xem trước phía client, file gốc mới được lưu). <span class="ref">docs/06 §3 endpoint 20</span> <span class="ref">FR-HS-08</span></span></li><li><span class="num">7</span><span>Ảnh tải lên chỉ đọc được bởi chính owner + ADMIN qua signed URL TTL ≤5 phút (<code>GET /media/{id}</code>) — wireframe không cần vẽ, nhưng FE không bao giờ embed URL công khai cho ảnh KYC. <span class="ref">NFR-S-05</span> <span class="ref">docs/07 §2.6</span></span></li><li><span class="num">8</span><span><b>2 ảnh bắt buộc</b>: thiếu ảnh nào báo lỗi ngay dưới dropzone ảnh đó; nút &quot;Tiếp tục&quot; disabled nêu rõ thiếu gì. Sai định dạng/quá 5MB → FE chặn trước khi upload, BE re-check: 413 <code>MEDIA_TOO_LARGE</code> / 400 <code>MEDIA_INVALID</code> → toast: &quot;Ảnh không hợp lệ — chỉ nhận JPEG/PNG/WEBP, tối đa 5MB&quot;. <span class="ref">BR-KYC-03</span> <span class="ref">FR-KYC-01</span> <span class="ref">UC-05 EF-2</span></span></li></ol></div><h2 id="_3-desktop-—-buoc-3-3-xac-nhan-gui-ho-so" tabindex="-1">3. Desktop — Bước 3/3: xác nhận &amp; gửi hồ sơ <a class="header-anchor" href="#_3-desktop-—-buoc-3-3-xac-nhan-gui-ho-so" aria-label="Permalink to &quot;3. Desktop — Bước 3/3: xác nhận &amp; gửi hồ sơ&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:640px;"><div class="wf-card"><div class="pad wf-col" style="gap:12px;"><span class="wf-title lg">Xác nhận hồ sơ <span class="wf-callout">9</span></span><div class="wf-steps"><span class="wf-step done">1 · Thông tin ✓</span><span class="wf-step done">2 · Ảnh ✓</span><span class="wf-step active">3 · Xác nhận &amp; gửi</span></div><div class="wf-col" style="gap:6px;"><div class="wf-row between"><span class="wf-text">Họ tên (trên CCCD)</span><span class="wf-strong">NGUYỄN VĂN DEMO</span></div><div class="wf-row between"><span class="wf-text">Ngày sinh</span><span class="wf-strong">20/05/1990</span></div><div class="wf-row between"><span class="wf-text">Số CCCD</span><span class="wf-strong">001090123456</span></div></div><div class="wf-grid"><div class="wf-img" style="min-height:90px;"><span>MẶT TRƯỚC</span></div><div class="wf-img" style="min-height:90px;"><span>MẶT SAU</span></div></div><span class="wf-checkbox checked"><span class="wf-text">Tôi xác nhận thông tin trên là đúng sự thật và đồng ý AnPhucRealEstate xử lý dữ liệu cá nhân nhạy cảm của tôi theo Nghị định 13/2023/NĐ-CP (phạm vi đã nêu ở Bước 1)</span></span><div class="wf-note"><b>Sau khi gửi không thể chỉnh sửa</b> — hồ sơ chuyển sang chờ duyệt. Muốn thay đổi thông tin/ảnh phải chờ kết quả và nộp hồ sơ mới. <span class="wf-callout warn">10</span></div><div class="wf-row between"><span class="wf-btn ghost">← Bước 2</span><span class="wf-btn primary lg">GỬI HỒ SƠ XÁC MINH <span class="wf-callout" style="background:#fff;color:var(--wf-accent);">11</span></span></div><span class="wf-small wf-center">Kết quả duyệt: chậm nhất <b>48 giờ</b> (SLA) — thông báo qua 🔔 trong app + email demo@example.com</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích bước xác nhận</div><ol><li><span class="num">9</span><span>Màn tổng hợp để user <b>tự đối chiếu lần cuối</b> — hiện đúng dữ liệu sẽ gửi (<code>POST /users/me/kyc</code>: fullName, dateOfBirth, cccdNumber, frontMediaId, backMediaId). Sai ở đây = bị reject tốn 48h + tốn 1/3 lượt nộp. <span class="ref">docs/06 §4.7</span></span></li><li><span class="num">10</span><span>Checkbox đồng ý xử lý dữ liệu <b>bắt buộc tick tại bước này</b> (không tick hộ từ bước 1); chưa tick → nút gửi disabled + field error &quot;Vui lòng xác nhận để gửi hồ sơ&quot;. <span class="ref">NĐ13</span> <span class="ref">NFR-S-05</span></span></li><li><span class="num">11</span><span>Submit: nút loading disabled chống double-submit → 201 <code>{state: PENDING, slaReviewBy}</code> → chuyển sang màn PENDING (mục 4) + toast ok &quot;Đã gửi hồ sơ — hẹn kết quả trước 12/10/2026 09:30 (GMT+7)&quot;. <span class="ref">docs/06 §4.7</span> <span class="ref">UC-02 MF</span></span></li></ol></div><h2 id="_4-trang-thai-pending-—-man-khoa-cho-duyet" tabindex="-1">4. Trạng thái PENDING — màn khóa chờ duyệt <a class="header-anchor" href="#_4-trang-thai-pending-—-man-khoa-cho-duyet" aria-label="Permalink to &quot;4. Trạng thái PENDING — màn khóa chờ duyệt&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:640px;"><span class="wf-state-label">TRẠNG THÁI: KYC = PENDING (FORM KHÓA HOÀN TOÀN)</span><div class="wf-card" style="border-width:2px;border-color:var(--wf-warn);"><div class="pad wf-col" style="gap:12px;"><div class="wf-row between middle"><span class="wf-badge warn">⏳ ĐANG CHỜ DUYỆT</span><span class="wf-small">mã hồ sơ ky_01JZK3M9W2…</span></div><span class="wf-title lg">Hồ sơ đang chờ ADMIN duyệt — không cần làm gì thêm</span><div class="wf-col" style="gap:6px;"><div class="wf-row between"><span class="wf-text">Nộp lúc</span><span class="wf-strong">10/10/2026 09:30 (GMT+7)</span></div><div class="wf-row between"><span class="wf-text">Hẹn trả kết quả trước</span><span class="wf-strong">12/10/2026 09:30 (GMT+7) — SLA ≤48 giờ</span></div><div class="wf-row between"><span class="wf-text">Lượt nộp trong 30 ngày</span><span class="wf-strong">1/3</span></div></div><div class="wf-note">Trong thời gian chờ: <b>không thể nộp hồ sơ mới hay chỉnh sửa</b> (chỉ 1 hồ sơ PENDING tại một thời điểm). Bạn vẫn xem tin, xem phiên đấu giá bình thường — các tính năng đăng tin/đấu giá/đặt lịch mở ngay khi có kết quả. <span class="wf-callout warn">12</span></div><span class="wf-small wf-muted">Quá 48 giờ chưa có kết quả? Gọi CSKH 1900-xxx (kèm mã hồ sơ) — không cần nộp lại.</span><span class="wf-btn block">Về Dashboard → SC-20</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích PENDING</div><ol><li><span class="num">12</span><span>PENDING = <b>lock screen</b>: thay toàn bộ wizard bằng panel trạng thái — không hiện form nửa vời dễ tưởng sửa được. Chỉ 1 application PENDING/user; mỗi lần nộp là 1 application mới (không &quot;đè&quot; hồ sơ cũ). Kết quả về → NTF in-app + email; vào lại /xac-minh tự render trạng thái mới. <span class="ref">BR-KYC-05</span> <span class="ref">UC-02 AF-2</span> <span class="ref">BR-ADM-03</span> <span class="ref">FR-NTF-02</span></span></li></ol></div><h2 id="_5-trang-thai-rejected-—-banner-ly-do-nguyen-van-nop-lai" tabindex="-1">5. Trạng thái REJECTED — banner lý do nguyên văn + nộp lại <a class="header-anchor" href="#_5-trang-thai-rejected-—-banner-ly-do-nguyen-van-nop-lai" aria-label="Permalink to &quot;5. Trạng thái REJECTED — banner lý do nguyên văn + nộp lại&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:640px;gap:12px;"><span class="wf-state-label">TRẠNG THÁI: KYC = REJECTED (CÒN LƯỢT NỘP LẠI)</span><div class="wf-card" style="border-width:2px;border-color:var(--wf-danger);"><div class="pad wf-col" style="gap:12px;"><div class="wf-row between middle"><span class="wf-badge danger">✗ HỒ SƠ BỊ TỪ CHỐI</span><span class="wf-small">duyệt lúc 11/10/2026 15:10 (GMT+7)</span></div><span class="wf-title">Lý do từ chối (nguyên văn từ bộ phận duyệt) <span class="wf-callout danger">13</span></span><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);"> &quot;Ảnh mặt sau bị mờ phần số CCCD và che góc dưới bên phải — vui lòng chụp lại trên nền phẳng, đủ sáng, thấy đủ 4 góc thẻ.&quot; </div><div class="wf-col" style="gap:6px;"><div class="wf-row between"><span class="wf-text">Lượt nộp trong 30 ngày</span><span class="wf-strong">2/3 — còn 1 lượt trước khi bị giới hạn <span class="wf-callout warn">14</span></span></div><div class="wf-row between"><span class="wf-text">Hồ sơ bị từ chối</span><span class="wf-strong">ky_01JZK…M9W2 (không thể sửa — chỉ xem)</span></div></div><span class="wf-btn primary lg block">NỘP LẠI HỒ SƠ → BƯỚC 1 <span class="wf-callout" style="background:#fff;color:var(--wf-accent);">15</span></span><span class="wf-small wf-muted">Thông tin bước 1 được prefill từ hồ sơ cũ — bắt buộc tải lại đủ 2 ảnh mới. Nộp lại tạo hồ sơ mới, hồ sơ cũ giữ nguyên làm lịch sử.</span></div></div><span class="wf-state-label">TRẠNG THÁI: HẾT LƯỢT NỘP (422 KYC_ATTEMPT_LIMIT)</span><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><div class="wf-toast danger">Bạn đã nộp 3 hồ sơ trong 30 ngày — tạm thời không thể nộp tiếp <span class="wf-callout danger">16</span></div><span class="wf-text">Giới hạn chống lạm dụng: tối đa 3 hồ sơ (kể cả nộp lại) trong 30 ngày gần nhất. Đừng lo — hồ sơ và lý do từ chối vẫn xem được bên dưới.</span><span class="wf-btn block">Gọi CSKH 1900-xxx để được hỗ trợ trực tiếp</span><span class="wf-btn disabled block">Nộp lại hồ sơ (khóa — hết lượt 30 ngày)</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích REJECTED</div><ol><li><span class="num">13</span><span>Lý do reject hiển thị <b>nguyên văn</b> (ADMIN bắt buộc nhập 10–500 ký tự) — FE không tóm tắt, không viết lại, không dịch giọng. Design khung reason nổi bật nhưng không &quot;đổ lỗi&quot; (kèm hướng sửa cụ thể do ADMIN viết). <span class="ref">BR-KYC-04</span> <span class="ref">FR-KYC-02</span></span></li><li><span class="num">14</span><span>Đếm lượt <b>3 hồ sơ/30 ngày rolling</b> hiện công khai để user không &quot;đốt&quot; lượt bừa; ngày mở khóa lại = ngày hồ sơ đầu tiên rơi khỏi cửa sổ 30 ngày. <span class="ref">BR-KYC-06</span> <span class="ref">FR-KYC-03</span></span></li><li><span class="num">15</span><span>Nộp lại = application mới (PENDING mới), hồ sơ REJECTED cũ terminal; user chỉ có 1 PENDING tại một thời điểm. <span class="ref">UC-02 AF-2</span> <span class="ref">BR-KYC-05</span> <span class="ref">docs/08 §10.6</span></span></li><li><span class="num">16</span><span>Vượt giới hạn → 422 <code>KYC_ATTEMPT_LIMIT</code>: nút nộp disabled hẳn + lối thoát duy nhất là CSKH (copy hướng dẫn liên hệ CS theo UC-02 EF-3). <span class="ref">UC-02 EF-3</span> <span class="ref">FR-KYC-03</span></span></li></ol></div><h2 id="_6-trang-thai-approved-—-đa-xac-minh" tabindex="-1">6. Trạng thái APPROVED — đã xác minh <a class="header-anchor" href="#_6-trang-thai-approved-—-đa-xac-minh" aria-label="Permalink to &quot;6. Trạng thái APPROVED — đã xác minh&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:640px;"><span class="wf-state-label">TRẠNG THÁI: KYC = APPROVED</span><div class="wf-card" style="border-width:2px;border-color:var(--wf-ok);"><div class="pad wf-col" style="gap:12px;"><div class="wf-row between middle"><span class="wf-badge ok">✓ ĐÃ XÁC MINH · 08/10/2026 09:30 (GMT+7)</span><span class="wf-small">CCCD 001090123456</span></div><span class="wf-title lg">Danh tính đã được xác minh — bạn đã mở toàn bộ tính năng <span class="wf-callout">17</span></span><div class="wf-col" style="gap:6px;"><span class="wf-text wf-ok-text">✓ Đăng tin bán căn hộ NOXH (hạn mức gói FREE: 2 tin)</span><span class="wf-text wf-ok-text">✓ Đăng ký tham gia đấu giá + đặt cọc</span><span class="wf-text wf-ok-text">✓ Đặt lịch xem nhà với chủ nhà đã xác minh</span></div><div class="wf-row" style="gap:8px;"><span class="wf-btn primary" style="flex:1;">Đăng tin đầu tiên → SC-22</span><span class="wf-btn" style="flex:1;">Xem phiên sắp mở → SC-05</span></div><span class="wf-small wf-muted">Thông tin đã xác minh <b>không thể tự sửa</b> — sai sót (đổi CCCD, sai tên) liên hệ CSKH 1900-xxx để được hướng dẫn.</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích APPROVED</div><ol><li><span class="num">17</span><span>APPROVED là điều kiện tiên quyết của 3 nhóm tính năng — màn xác nhận liệt kê đúng 3 nhóm đó (khớp BR-KYC-08) rồi đẩy user đi tiếp ngay, không để màn &quot;chúc mừng&quot; chết. Số CCCD hiện cho chính chủ xem (của user thì user thấy); với người khác luôn bị ẩn. Wizard thay bằng panel trạng thái; không còn nút &quot;nộp lại&quot;. <span class="ref">BR-KYC-08</span> <span class="ref">BR-IDT-06</span> <span class="ref">NFR-S-05</span></span></li></ol></div><h2 id="_7-trang-thai-loi-bien-bat-buoc-thiet-ke-đu" tabindex="-1">7. Trạng thái lỗi &amp; biên (bắt buộc thiết kế đủ) <a class="header-anchor" href="#_7-trang-thai-loi-bien-bat-buoc-thiet-ke-đu" aria-label="Permalink to &quot;7. Trạng thái lỗi &amp; biên (bắt buộc thiết kế đủ)&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">409 — CCCD ĐÃ GẮN TÀI KHOẢN KHÁC</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Số CCCD</span><div class="wf-input filled error"><span>001090123456</span><span class="caret">✎</span></div><span class="wf-field-error">Giấy tờ này đã được liên kết tài khoản khác, liên hệ CS <span class="wf-callout danger">18</span></span></div><span class="wf-small">1 CCCD chỉ thuộc đúng 1 tài khoản đã xác minh. Nếu bạn nghi bị mạo danh — gọi ngay CSKH 1900-xxx để điều tra, KHÔNG tạo tài khoản mới nộp lại.</span></div></div></div><div class="wf-col"><span class="wf-state-label">422 — CHƯA ĐỦ 18 TUỔI (KYC_UNDERAGE)</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Ngày sinh</span><div class="wf-input filled error"><span>15/12/2010</span><span class="caret">📅</span></div><span class="wf-field-error">Bạn phải đủ 18 tuổi tại thời điểm nộp hồ sơ</span></div><span class="wf-small">Tuổi tính theo giờ server (không tin đồng hồ máy khách). Người dưới 18 không thuộc đối tượng đứng tên giao dịch NOXH trên sàn — không có đường &quot;lách&quot; nào trên UI.</span></div></div></div><div class="wf-col"><span class="wf-state-label">400/413 — ẢNH SAI ĐỊNH DẠNG / QUÁ 5MB</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-toast danger">Ảnh không hợp lệ — chỉ nhận JPEG/PNG/WEBP, tối đa 5MB</div><div class="wf-img" style="min-height:80px;border-style:dashed;"><span>DROPZONE GIỮ NGUYÊN — THẢ ẢNH KHÁC VÀO ĐÂY</span></div><span class="wf-small">FE chặn trước khi upload (MIME + dung lượng); BE re-check trả <code>MEDIA_INVALID</code>/<code>MEDIA_TOO_LARGE</code>. Toast chỉ rõ cách sửa, không hiện mã lỗi thô cho user.</span></div></div></div><div class="wf-col"><span class="wf-state-label">ERROR MẠNG / 500 KHI GỬI HỒ SƠ</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-error-box"><b>Không gửi được hồ sơ — dữ liệu của bạn vẫn được giữ trên trang này</b><div class="wf-small" style="margin:6px 0;">Kiểm tra kết nối rồi thử lại. Nếu lỗi lặp lại, báo CSKH 1900-xxx kèm mã bên dưới.</div><span class="wf-trace">traceId: 3f9a…c21d</span></div><span class="wf-btn primary block">Thử gửi lại</span><span class="wf-small">Retry không tạo hồ sơ trùng: nếu server đã nhận (PENDING tồn tại) → màn tự chuyển sang trạng thái PENDING. <span class="wf-callout">19</span></span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích lỗi &amp; biên</div><ol><li><span class="num">18</span><span>409 <code>KYC_ID_ALREADY_VERIFIED</code> — copy theo UC-02 EF-1; hệ thống so qua <b>hash CCCD</b> của các hồ sơ APPROVED nên không lộ dữ liệu tài khoản kia. Đây cũng là lý do không cho user tự &quot;thử CCCD khác&quot;. <span class="ref">BR-IDT-06</span> <span class="ref">UC-02 EF-1</span> <span class="ref">docs/07 §2.3</span></span></li><li><span class="num">19</span><span>4 trạng thái nền của màn: <b>Loading</b> = skeleton card form khi đọc <code>GET /users/me/kyc</code>; <b>Error</b> = hộp lỗi + traceId như ô trên; <b>Empty</b> = wizard bước 1 (mục 1); <b>Data</b> = các panel trạng thái (mục 4/5/6). Ảnh đã upload thành công không bị mất khi form lỗi. <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_8-mobile-360px-—-buoc-1-va-buoc-2" tabindex="-1">8. Mobile 360px — bước 1 và bước 2 <a class="header-anchor" href="#_8-mobile-360px-—-buoc-1-va-buoc-2" aria-label="Permalink to &quot;8. Mobile 360px — bước 1 và bước 2&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;gap:20px;flex-wrap:wrap;"><div><span class="wf-state-label">MOBILE — BƯỚC 1: THÔNG TIN CCCD</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">NĐ</span></span></div><div class="wf-container" style="padding:12px;"><div class="wf-col" style="gap:10px;"><span class="wf-title">Xác minh danh tính (CCCD)</span><div class="wf-steps"><span class="wf-step active">1</span><span class="wf-step">2</span><span class="wf-step">3</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Họ tên (trên CCCD) *</span><div class="wf-input filled"><span>NGUYỄN VĂN DEMO</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Ngày sinh *</span><div class="wf-input filled"><span>20/05/1990</span><span class="caret">📅</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Số CCCD (12 số) *</span><div class="wf-input filled"><span>001090123456</span><span class="caret">✎</span></div></div><div class="wf-note"><b>🔒 NĐ13:</b> số + ảnh CCCD mã hóa AES-256, chỉ ADMIN duyệt xem được (link 5 phút), không public; hồ sơ reject quá 180 ngày tự xóa.</div><span class="wf-btn primary block">Tiếp tục → Bước 2</span></div></div></div></div><div><span class="wf-state-label">MOBILE — BƯỚC 2: ẢNH 2 MẶT</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">NĐ</span></span></div><div class="wf-container" style="padding:12px;"><div class="wf-col" style="gap:10px;"><span class="wf-title">Ảnh CCCD 2 mặt</span><div class="wf-steps"><span class="wf-step done">1 ✓</span><span class="wf-step active">2</span><span class="wf-step">3</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">MẶT TRƯỚC *</span><div class="wf-img" style="min-height:110px;"><span>ẢNH ĐÃ TẢI — CHẠM ĐỂ XEM LỚN</span></div><span class="wf-small wf-ok-text">✓ Đã sẵn sàng</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">MẶT SAU *</span><div class="wf-img" style="min-height:110px;border-style:dashed;"><span>CHẠM ĐỂ CHỤP / CHỌN ẢNH</span></div><span class="wf-field-error">Bắt buộc đủ 2 ảnh</span></div><span class="wf-small">JPEG/PNG/WEBP · ≤5MB · đủ sáng, thấy đủ 4 góc</span><span class="wf-btn disabled block">Tiếp tục (thiếu mặt sau)</span></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>Mobile là kênh chính chụp CCCD: dropzone mở <b>camera trước, thư viện sau</b>; 2 dropzone xếp dọc; step bar rút gọn còn số bước. Cảnh báo NĐ13 giữ nguyên văn bản đầy đủ (rút tiêu đề, không cắt nội dung pháp lý).</span></li></ol></div><h2 id="_9-checklist-designer-khi-dung-figma-cho-sc-21" tabindex="-1">9. Checklist designer khi dựng Figma cho SC-21 <a class="header-anchor" href="#_9-checklist-designer-khi-dung-figma-cho-sc-21" aria-label="Permalink to &quot;9. Checklist designer khi dựng Figma cho SC-21&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (card 640px giữa trang) / mobile 360 (camera-first) / tablet 768</li><li>[ ] Đủ 3 bước wizard + 3 panel trạng thái (PENDING lock · REJECTED reason · APPROVED) + biến thể hết lượt nộp (ATTEMPT_LIMIT)</li><li>[ ] Cảnh báo NĐ13 nổi bật ở BƯỚC 1 (không giấu ở bước cuối): mã hóa AES-256 · signed URL 5 phút · không public · purge 180 ngày</li><li>[ ] Validation: CCCD đúng 12 số (đếm 12/12), DOB ≥18 (giờ server), 2 ảnh bắt buộc JPEG/PNG/WEBP ≤5MB, tên trùng CCCD hint BR-KYC-02</li><li>[ ] Reason REJECTED hiển thị nguyên văn trong khung riêng + đếm lượt nộp lại x/3 (30 ngày); prefill khi nộp lại</li><li>[ ] Copy đúng docs/06 §5 + UC-02: &quot;Giấy tờ này đã được liên kết tài khoản khác, liên hệ CS&quot; · &quot;Bạn phải đủ 18 tuổi tại thời điểm nộp hồ sơ&quot;; lỗi mạng kèm traceId rút gọn</li><li>[ ] Ngày giờ <code>dd/MM/yyyy HH:mm</code> (GMT+7): nộp lúc, hẹn SLA 48h, duyệt lúc</li><li>[ ] Không emoji icon trong UI production (🔒/📅/⏳/✓ trong wireframe là placeholder vị trí — thay icon set thật)</li><li>[ ] Accessibility: dropzone dùng được bằng bàn phím + label; field error aria-live; contrast AA cho chữ đỏ trên nền danger-soft; không truyền đạt trạng thái chỉ bằng màu</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ (vd SLA 48h, giới hạn 3 lần/30 ngày, retention NĐ13) cần PM + Pháp chế duyệt trên docs/08 trước.</p></div>',30)])])}const f=a(i,[["render",t]]);export{g as __pageData,f as default};
